        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = False
        self.strategy_b_pending = False
        self.order_owners = {}

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        previous_spy_sma_50 = (
            self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
        )
        previous_spy_sma_200 = (
            self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
        )

        if spy_bar is not None:
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            if spy_bar is not None:
                self.spy_previous_close = spy_bar.Close
            if aapl_bar is not None:
                self.aapl_previous_close = aapl_bar.Close
            return

        spy_close = spy_bar.Close
        aapl_close = aapl_bar.Close

        if self.strategy_a_lot > 0 and not self.strategy_a_pending:
            price_crosses_below_sma_50 = (
                self.spy_previous_close is not None
                and previous_spy_sma_50 is not None
                and self.spy_sma_50.IsReady
                and self.spy_previous_close >= previous_spy_sma_50
                and spy_close < self.spy_sma_50.Current.Value
            )

            if price_crosses_below_sma_50:
                self._submit_order("A", self.spy, -self.strategy_a_lot)

        if self.strategy_b_lot > 0 and not self.strategy_b_pending:
            if self.aapl_rsi_14.IsReady and self.aapl_rsi_14.Current.Value > 60:
                self._submit_order("B", self.aapl, -self.strategy_b_lot)

        if self.strategy_a_lot == 0 and not self.strategy_a_pending:
            close_crosses_above_sma_200 = (
                self.spy_previous_close is not None
                and previous_spy_sma_200 is not None
                and self.spy_sma_200.IsReady
                and self.spy_previous_close <= previous_spy_sma_200
                and spy_close > self.spy_sma_200.Current.Value
            )

            if close_crosses_above_sma_200:
                quantity = math.floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_close)
                )
                if quantity > 0:
                    self._submit_order("A", self.spy, quantity)

        if self.strategy_b_lot == 0 and not self.strategy_b_pending:
            if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                quantity = math.floor(20_000 / float(aapl_close))
                if quantity > 0:
                    self._submit_order("B", self.aapl, quantity)

        self.spy_previous_close = spy_close
        self.aapl_previous_close = aapl_close

    def _submit_order(self, strategy, symbol, quantity):
        if quantity == 0:
            return

        if strategy == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

        ticket = self.MarketOrder(symbol, quantity)
        self.order_owners[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        if order_event.OrderId not in self.order_owners:
            return

        strategy = self.order_owners[order_event.OrderId]

        if order_event.FillQuantity != 0:
            if strategy == "A":
                self.strategy_a_lot += order_event.FillQuantity
            else:
                self.strategy_b_lot += order_event.FillQuantity

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

            self.order_owners.pop(order_event.OrderId, None)
