from AlgorithmImports import *
from collections import deque
import math


class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=201)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.rsi_seed_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.a_lot = 0
        self.b_lot = 0
        self.a_pending = False
        self.b_pending = False

    def OnData(self, data):
        # Market-state quantities continue updating whenever their own bar exists.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            self._update_aapl_state(float(data.Bars[self.aapl].Close))

        # A missing bar for any subscribed ticker suppresses all rule evaluation.
        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        # No trading until all indicators and rolling windows are fully formed.
        if not self._ready():
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        # Sells are evaluated before buys.
        if self.a_lot > 0 and not self.a_pending and self._spy_crosses_below_sma50():
            self.a_pending = True
            self.MarketOrder(self.spy, -self.a_lot, tag="A_SELL")

        if self.b_lot > 0 and not self.b_pending and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.b_pending = True
            self.MarketOrder(self.aapl, -self.b_lot, tag="B_SELL")

        if self.a_lot == 0 and not self.a_pending and self._spy_crosses_above_sma200():
            quantity = int(math.floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
            ))
            if quantity > 0:
                self.a_pending = True
                self.MarketOrder(self.spy, quantity, tag="A_BUY")

        if self.b_lot == 0 and not self.b_pending and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                quantity = int(math.floor(20_000 / aapl_close))
                if quantity > 0:
                    self.b_pending = True
                    self.MarketOrder(self.aapl, quantity, tag="B_BUY")

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                order = self.Transactions.GetOrderById(order_event.OrderId)
                if order is not None:
                    if order.Tag.startswith("A_"):
                        self.a_pending = False
                    elif order.Tag.startswith("B_"):
                        self.b_pending = False
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "A_BUY":
            self.a_lot += order_event.FillQuantity
        elif order.Tag == "A_SELL":
            self.a_lot = max(0, self.a_lot + order_event.FillQuantity)
        elif order.Tag == "B_BUY":
            self.b_lot += order_event.FillQuantity
        elif order.Tag == "B_SELL":
            self.b_lot = max(0, self.b_lot + order_event.FillQuantity)

        if order_event.Status == OrderStatus.Filled:
            if order.Tag.startswith("A_"):
                self.a_pending = False
            elif order.Tag.startswith("B_"):
                self.b_pending = False

    def _ready(self):
        return (
            len(self.spy_closes) == 201
            and self.rsi_seed_count >= 14
            and self.aapl_rsi is not None
        )

    def _spy_crosses_above_sma200(self):
        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_sma = sum(closes[:-1]) / 200.0
        today_sma = sum(closes[-200:]) / 200.0
        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _spy_crosses_below_sma50(self):
        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_sma = sum(closes[-51:-1]) / 50.0
        today_sma = sum(closes[-50:]) / 50.0
        return yesterday_close >= yesterday_sma and today_close < today_sma

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = close - self.aapl_previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_seed_count < 14:
                self.rsi_gain_sum += gain
                self.rsi_loss_sum += loss
                self.rsi_seed_count += 1

                if self.rsi_seed_count == 14:
                    self.rsi_average_gain = self.rsi_gain_sum / 14.0
                    self.rsi_average_loss = self.rsi_loss_sum / 14.0
                    self.aapl_rsi = self._calculate_rsi()
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * 13.0) + gain
                ) / 14.0
                self.rsi_average_loss = (
                    (self.rsi_average_loss * 13.0) + loss
                ) / 14.0
                self.aapl_rsi = self._calculate_rsi()

        self.aapl_previous_close = close

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0
        if self.rsi_average_gain == 0:
            return 0.0
        rs = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + rs))
