            change = close - self.aapl_previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_seed_count < 14:
                self.rsi_gain_sum += gain
                self.rsi_loss_sum += loss
                self.rsi_seed_count += 1

                if self.rsi_seed_count == 14:
                    self.rsi_average_gain = self.rsi_gain_sum / 14.0
                    self.rsi_average_loss = self.rsi_loss_sum / 14.0
                    self.aapl_rsi = self._calculate_rsi()
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * 13.0) + gain
                ) / 14.0
                self.rsi_average_loss = (
                    (self.rsi_average_loss * 13.0) + loss
                ) / 14.0
                self.aapl_rsi = self._calculate_rsi()

        self.aapl_previous_close = close

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0
        if self.rsi_average_gain == 0:
            return 0.0
        rs = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + rs))

